document.addEventListener('DOMContentLoaded',()=>{const grid=document.getElementById('categoriesGrid');const cards=Array.from(document.querySelectorAll('.category-full-card'));const searchInput=document.getElementById('categorySearch');const sortTabs=document.querySelectorAll('.filter-tab');const resultsCount=document.getElementById('resultsCount');const noResults=document.getElementById('noResults');function applySearch(){const query=(searchInput?.value||'').trim();let visibleCount=0;cards.forEach(card=>{const visible=!query||card.dataset.name.includes(query);card.hidden=!visible;if(visible)visibleCount++});resultsCount.textContent=visibleCount;noResults.hidden=visibleCount!==0;grid.hidden=visibleCount===0}
searchInput?.addEventListener('input',applySearch);sortTabs.forEach(tab=>{tab.addEventListener('click',()=>{sortTabs.forEach(t=>t.classList.remove('active'));tab.classList.add('active');const sort=tab.dataset.sort;let sorted=cards;if(sort==='popular'){sorted=[...cards].sort((a,b)=>b.dataset.count-a.dataset.count)}else if(sort==='az'){sorted=[...cards].sort((a,b)=>a.dataset.name.localeCompare(b.dataset.name,'ar'))}
sorted.forEach(card=>grid.appendChild(card))})})})